  {
    "statement": "IF arguments[\"tool_name\"] ∈ {\"verify_warehouse_receipt\", \"check_inventory_iot\", \"analyze_trade_chain\", \"reject_request\", \"escalate_to_compliance\"} THEN policy returns (True, any message) – i.e., the call is always allowed."
  },
  {
    "statement": "IF arguments[\"tool_name\"] == \"approve_pledge_loan\" AND arguments[\"verify_warehouse_receipt_status\"] == \"success\" AND arguments[\"verify_warehouse_receipt_is_valid\"] == true AND arguments[\"verify_warehouse_receipt_already_pledged\"] == false AND arguments[\"check_inventory_iot_status\"] == \"success\" AND arguments[\"check_inventory_iot_iot_verified\"] == true AND arguments[\"check_inventory_iot_quantity_mismatch\"] == false AND arguments[\"analyze_trade_chain_status\"] == \"success\" AND arguments[\"analyze_trade_chain_is_circular\"] == false AND arguments[\"analyze_trade_chain_related_parties\"] == false THEN policy returns (True, \"All required verifications succeeded; loan approval allowed.\")"
  },
  {
    "statement": "IF arguments[\"tool_name\"] == \"approve_pledge_loan\" AND (arguments[\"verify_warehouse_receipt_status\"] is None OR arguments[\"verify_warehouse_receipt_is_valid\"] is None OR arguments[\"verify_warehouse_receipt_already_pledged\"] is None OR arguments[\"check_inventory_iot_status\"] is None OR arguments[\"check_inventory_iot_iot_verified\"] is None OR arguments[\"check_inventory_iot_quantity_mismatch\"] is None OR arguments[\"analyze_trade_chain_status\"] is None OR arguments[\"analyze_trade_chain_is_circular\"] is None OR arguments[\"analyze_trade_chain_related_parties\"] is None) THEN policy returns (False, \"Missing required verification result: <field>.\")"
  },
  {
    "statement": "IF arguments[\"tool_name\"] == \"approve_pledge_loan\" AND arguments[\"verify_warehouse_receipt_status\"] != \"success\" THEN policy returns (False, \"Verification failed (warehouse receipt status): expected success, got <value>.\")"
  },
  {
    "statement": "IF arguments[\"tool_name\"] == \"approve_pledge_loan\" AND arguments[\"verify_warehouse_receipt_is_valid\"] != true THEN policy returns (False, \"Verification failed (warehouse receipt validity): expected true, got <value>.\")"
  },
  {
    "statement": "IF arguments[\"tool_name\"] == \"approve_pledge_loan\" AND arguments[\"verify_warehouse_receipt_already_pledged\"] != false THEN policy returns (False, \"Verification failed (warehouse receipt pledge state): expected false, got <value>.\")"
  },
  {
    "statement": "IF arguments[\"tool_name\"] == \"approve_pledge_loan\" AND arguments[\"check_inventory_iot_status\"] != \"success\" THEN policy returns (False, \"Verification failed (inventory IoT status): expected success, got <value>.\")"
  },
  {
    "statement": "IF arguments[\"tool_name\"] == \"approve_pledge_loan\" AND arguments[\"check_inventory_iot_iot_verified\"] != true THEN policy returns (False, \"Verification failed (IoT verification flag): expected true, got <value>.\")"
  },
  {
    "statement": "IF arguments[\"tool_name\"] == \"approve_pledge_loan\" AND arguments[\"check_inventory_iot_quantity_mismatch\"] != false THEN policy returns (False, \"Verification failed (quantity mismatch flag): expected false, got <value>.\")"
  },
  {
    "statement": "IF arguments[\"tool_name\"] == \"approve_pledge_loan\" AND arguments[\"analyze_trade_chain_status\"] != \"success\" THEN policy returns (False, \"Verification failed (trade chain analysis status): expected success, got <value>.\")"
  },
  {
    "statement": "IF arguments[\"tool_name\"] == \"approve_pledge_loan\" AND arguments[\"analyze_trade_chain_is_circular\"] != false THEN policy returns (False, \"Verification failed (circular trade flag): expected false, got <value>.\")"
  },
  {
    "statement": "IF arguments[\"tool_name\"] == \"approve_pledge_loan\" AND arguments[\"analyze_trade_chain_related_parties\"] != false THEN policy returns (False, \"Verification failed (related parties flag): expected false, got <value>.\")"
  },
  {
    "statement": "IF arguments[\"tool_name\"] == \"approve_pledge_loan\" AND any of the above verification conditions is false (missing or mismatched) THEN the loan must be rejected or escalated using the always‑allowed tools; the policy must return (False, <explanation>) and never permit the call to approve_pledge_loan."
  },
  {
    "statement": "IF arguments[\"tool_name\"] is not in ALWAYS_ALLOWED_TOOLS and not equal to \"approve_pledge_loan\" THEN policy returns (True, \"Tool '<tool>' is not subject to additional checks.\")"
  }
]

The policy therefore enforces that the high‑risk `approve_pledge_loan` can only succeed when **all** required verification tool results are present and exactly match the approved values; any missing result, error status, or negative risk flag causes a denial, while the listed low‑risk tools are always permitted. This directly implements the security request’s pre‑conditions and post‑conditions.

