  {
    "statement": "IF tool_name == \"approve_pledge_loan\" AND verify_warehouse_receipt_status == \"success\" AND verify_warehouse_receipt_is_valid == true AND verify_warehouse_receipt_already_pledged == false AND check_inventory_iot_status == \"success\" AND check_inventory_iot_iot_verified == true AND check_inventory_iot_quantity_mismatch == false AND analyze_trade_chain_status == \"success\" AND analyze_trade_chain_is_circular == false AND analyze_trade_chain_related_parties == false THEN allow the call and the response MUST contain ONLY the fields \"status\" and \"approval_id\"."
  },
  {
