  },
  {
    "statement": "IF tool_name == \"approve_pledge_loan\" AND (verify_warehouse_receipt_is_valid == false OR verify_warehouse_receipt_already_pledged == true OR check_inventory_iot_iot_verified == false OR check_inventory_iot_quantity_mismatch == true OR analyze_trade_chain_is_circular == true OR analyze_trade_chain_related_parties == true) THEN deny the call and the system MUST immediately invoke \"reject_request\"."
  },
  {
    "statement": "IF tool_name == \"approve_pledge_loan\" AND any of the required verification fields (verify_warehouse_receipt_status, verify_warehouse_receipt_is_valid, verify_warehouse_receipt_already_pledged, check_inventory_iot_status, check_inventory_iot_iot_verified, check_inventory_iot_quantity_mismatch, analyze_trade_chain_status, analyze_trade_chain_is_circular, analyze_trade_chain_related_parties) is missing OR is null THEN deny the call and MUST invoke \"escalate_to_compliance\"."
  },
  {
    "statement": "IF tool_name == \"approve_pledge_loan\" AND more than one successful record exists for any verification type AND the records contain conflicting boolean values THEN deny the call and MUST invoke \"escalate_to_compliance\"."
  },
  {
    "statement": "IF tool_name == \"approve_pledge_loan\" AND the cryptographic hash (or internal flag) of any recorded successful verification does NOT match the hash stored for the current workflow session THEN deny the call and MUST invoke \"escalate_to_compliance\"."
  },
  {
    "statement": "IF tool_name == \"approve_pledge_loan\" AND the three required verification tools have NOT been executed in the same workflow session (i.e., no recorded timestamps for all three) THEN deny the call and MUST invoke \"escalate_to_compliance\"."
  },
  {
    "statement": "IF tool_name ∈ ALWAYS_ALLOWED_TOOLS THEN allow the call without any additional pre‑conditions."
  },
  {
    "statement": "IF tool_name ∉ ALL_KNOWN_TOOLS THEN deny the call and return the error \"Tool '{tool_name}' is not recognized and therefore not permitted.\""
  },
  {
    "statement": "IF tool_name ∉ ALWAYS_ALLOWED_TOOLS AND tool_name != \"approve_pledge_loan\" THEN deny the call (default‑deny) and return a clear error indicating the tool is not permitted."
  },
  {
    "statement": "IF tool_name == \"approve_pledge_loan\" AND the pre‑conditions of statement 1 are satisfied THEN the post‑condition is that no \"reject_request\" or \"escalate_to_compliance\" call is made; the only output is a deterministic response with fields \"status\" (e.g., \"success\") and a non‑null \"approval_id\"."
  },
  {
    "statement": "IF tool_name == \"approve_pledge_loan\" AND the call is denied by any of statements 2‑7 THEN exactly one remedial action must be taken: if the denial reason is a policy‑violating flag (already_pledged, quantity_mismatch, is_circular, related_parties) invoke \"reject_request\"; if the denial reason is an execution error or missing data invoke \"escalate_to_compliance\"."
  }
]

The statements encode all required pre‑conditions (successful, risk‑free verification results recorded in the current session, presence of non‑null fields, single source of truth, and integrity checks) and the corresponding post‑conditions (allowance with a deterministic approval response or mandatory rejection/escalation). They also enforce default‑deny for unknown or non‑always‑allowed tools, ensuring that the irreversible `approve_pledge_loan` can only be executed after verifiable, risk‑free checks.

